/**
 *
 * @param targetWindowIdentity Parent or Current OpenFin Window Identity
 * @param workspaceTitle The platform label that was selected to be switched to
 * @param shouldCenterOnMonitor Boolean - determines if modal window is centered on the monitor.
 * @returns Boolean - Affirmative or Negative response from user
 */
export const showSwitchWorkspaceModal = async (
    targetWindowIdentity: OpenFin.Identity | undefined,
    workspaceTitle: string,
    shouldCenterOnMonitor?: boolean
): Promise<boolean> => {
    const { windowOptions, content } = await getSwitchWorkspaceMenu(
        workspaceTitle,
        !shouldCenterOnMonitor ? targetWindowIdentity : undefined
    );

    const bounds = await getResponseModalBoundsAndCenterParentIfModalOffScreen(
        windowOptions,
        targetWindowIdentity,
        shouldCenterOnMonitor
    );

    const browserWindowCloseOptions = { ...windowOptions, top: bounds.top, left: bounds.left };
    const response = await waitForModalResponse({
        options: browserWindowCloseOptions,
        content
    });
    return response.data.actionName === 'Confirm';
};

