export const showUpdateVersionModal = async ({
    identity,
    title,
    description
}: {
    identity: OpenFin.Identity;
    title: string;
    description: string;
}): Promise<ModalResponseEvent['data']> => {
    const { windowOptions, content } = await getUpdateVersionModalConfig(identity, title, description);

    const modalWindow = fin.Window.wrapSync({
        uuid: identity.uuid,
        name: `${windowOptions.name}--${windowOptions.modalParentIdentity?.name}`
    });

    try {
        if (await modalWindow?.isShowing()) {
            logger.debug('showUpdateVersionModal', 'Modal already open, skipping creation');
            return;
        }
    } catch (_) {
        logger.debug('showUpdateVersionModal', 'Modal not open, creating new modal');
    }

    const bounds = await getResponseModalBoundsAndCenterParentIfModalOffScreen(
        windowOptions,
        windowOptions.modalParentIdentity
    );

    const browserWindowCloseOptions = { ...windowOptions, top: bounds.top, left: bounds.left };

    const response = await waitForModalResponse({
        options: browserWindowCloseOptions,
        content
    });
    return response.data;
};

